import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';
import type { Env } from '../../config/env.js';

/**
 * Where uploaded bytes live. Business code only knows this interface, so the
 * local-disk driver can be swapped for an S3-compatible one without touching it.
 * Keys are generated by the application (`<tenant>/<uuid>.<ext>`), never by users.
 */
export interface FileStorage {
  readonly driver: string;
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

export class LocalDiskStorage implements FileStorage {
  readonly driver = 'local';
  private readonly root: string;

  constructor(dir: string) {
    this.root = resolve(dir);
  }

  /** Resolves a key under the root and refuses anything that escapes it. */
  private pathOf(key: string): string {
    const full = resolve(this.root, key);
    if (!full.startsWith(this.root + sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const full = this.pathOf(key);
    await mkdir(dirname(full), { recursive: true });
    await writeFile(full, data, { flag: 'wx' });
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.pathOf(key));
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw err;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathOf(key), { force: true });
  }
}

/** In-memory driver for tests. */
export class MemoryStorage implements FileStorage {
  readonly driver = 'memory';
  readonly objects = new Map<string, Buffer>();
  async put(key: string, data: Buffer) {
    this.objects.set(key, data);
  }
  async get(key: string) {
    return this.objects.get(key) ?? null;
  }
  async delete(key: string) {
    this.objects.delete(key);
  }
}

export function createStorage(env: Env): FileStorage {
  if (env.STORAGE_DRIVER === 's3') {
    throw new Error('STORAGE_DRIVER=s3 is not implemented yet. Use STORAGE_DRIVER=local.');
  }
  return new LocalDiskStorage(env.STORAGE_DIR);
}
